<?php
require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/unified_experience_v1100.php';require_once __DIR__.'/app/local_assistant_booking_v1040.php';$flash='';$error='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();if((string)($_POST['action']??'')==='cancel'){sk1040_customer_cancel((int)($_POST['id']??0));$flash='Booking cancelled.';}}}catch(Throwable $e){$error=$e->getMessage();}$rows=sk1040_my_bookings();$csrf=csrf_token();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Bookings — ShahkotPK</title><link rel="stylesheet" href="/assets/local-assistant-v1040.css?v=1040"><?php sk1100_public_assets();?></head><body><?php sk1100_render_public_header(true);?><header class="la-top"><div class="la-shell"><a class="brand" href="/assistant-v1040.php">← Ask ShahkotPK</a><nav><a href="/my-shahkot.php">My Shahkot</a><a href="/booking-inbox-v1040.php">Provider Inbox</a></nav></div></header><main><section class="la-hero compact"><div class="la-shell"><span>MY BOOKINGS</span><h1>Your local appointments & booking requests</h1><p>Track pending, confirmed, rescheduled and completed bookings from one place.</p></div></section><section class="la-section"><div class="la-shell"><?php if($flash):?><div class="notice ok"><?=sk1040_h($flash)?></div><?php endif;?><?php if($error):?><div class="notice bad"><?=sk1040_h($error)?></div><?php endif;?><div class="booking-list"><?php foreach($rows as $r):?><article><div><small><?=sk1040_h((string)$r['booking_no'])?> · <?=sk1040_h(strtoupper((string)$r['entity_type']))?></small><h2><?=sk1040_h((string)$r['entity_title'])?></h2><p><?=sk1040_h(date('d M Y h:i A',strtotime((string)$r['requested_at'])))?> · <?=max(1,(int)$r['party_size'])?> person(s)</p><?php if(!empty($r['provider_note'])):?><p class="provider-note"><?=sk1040_h((string)$r['provider_note'])?></p><?php endif;?></div><div class="status-side"><span class="status <?=sk1040_h((string)$r['status'])?>"><?=sk1040_h(ucwords(str_replace('_',' ',(string)$r['status'])))?></span><?php if(in_array((string)$r['status'],['pending','confirmed','reschedule_requested'],true)):?><form method="post" onsubmit="return confirm('Cancel this booking?');"><input type="hidden" name="_csrf" value="<?=sk1040_h($csrf)?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="link danger">Cancel</button></form><?php endif;?></div></article><?php endforeach;?><?php if(!$rows):?><div class="empty"><h2>No bookings yet</h2><p>Use Ask ShahkotPK to find a local option and request a booking.</p><a href="/assistant-v1040.php">Open Assistant</a></div><?php endif;?></div></div></section></main><?php sk1100_render_ai_widget('public');?> </body></html>
